// src/utils/battery.ts
async function getBatteryStatus() {
	try {
		const nav = navigator;
		if (typeof nav.getBattery === "function") {
			const battery = await nav.getBattery();
			return {
				level: Math.round(battery.level * 100),
				charging: battery.charging,
				supported: true
			};
		}
	} catch (err) {}
	return {
		level: 84,
		charging: false,
		supported: false
	};
}
